+#ifndef TRITON_ASCEND_GRAPH_NARROW_UNSIGNED_TENSOR_H
+#define TRITON_ASCEND_GRAPH_NARROW_UNSIGNED_TENSOR_H
+
+#include "mlir/Dialect/Arith/IR/Arith.h"
+#include "mlir/IR/Matchers.h"
+#include "mlir/IR/PatternMatch.h"
